const proxy = require('express-http-proxy');

app.use('/docs/:docId/download', authenticateUser, async (req, res, next) => {
  const doc = await db.query(
    'SELECT id FROM user_documents WHERE id = $1 AND owner_id = $2',
    [req.params.docId, req.user.id]
  );
  if (doc.rowCount === 0) {
    return res.status(403).json({ error: 'Access denied: document does not belong to you' });
  }
  next();
}, proxy(process.env.STORAGE_MICROSERVICE_URL, {
  proxyReqPathResolver: (req) => {
    return `/internal/presign/documents/${req.params.docId}`;
  }
}));
